		let cleaned = false;
		const cleanup = () => {
			if (cleaned) return;
			cleaned = true;
			animations.forEach((animation) => animation.cancel());
			layout.replaceWith(...layout.childNodes);
			cell.classList.remove("cf-team-moving");
			active.delete(cell);
		};
